// ── source: vcx/tests/planar_delta_test.v ──
// planar_delta_test.v — the L101 ∂ battery (W7 of the I5 stream-2 ledger).
//
// Every maintained result is verified against the ENGINE recomputing the
// same comprehension over the same rows (the wave's done-when: maintained
// γ ≡ recompute), and every output ∂ script is verified by APPLYING it to
// the previous result — the script is the contract streams 3/4 consume,
// so it must reproduce the new relation, not merely describe it.
//
// The oracle substitutes the source references with literal-sequence
// sources and evaluates through code.eval_code — the general [?for] engine
// path, no membership gate — then both sides render through the same 'cx'
// renderer wrapped in a [rel …] element (full materialization; #771 makes
// a bare lazy comp render head-only through eval_code).

fn rows(texts []string) []cx.Node {
	mut out := []cx.Node{}
	for t in texts {
		doc := cx.parse(t) or { panic('row parse failed: ${err.msg()}\n${t}') }
		assert doc.elements.len == 1, 'row must be one element: ${t}'
		out << doc.elements[0]
	}
	return out
}

fn seq_text(texts []string) string {
	if texts.len == 0 {
		return '()'
	}
	return '(${texts.join(', ')})'
}

// oracle evaluates the comprehension over literal rows through the engine
// and returns the rendered [rel …] relation.
fn oracle(comp_with_placeholders string, subs map[string]string) string {
	mut src := comp_with_placeholders
	for k, v in subs {
		src = src.replace(k, v)
	}
	prog := '[?let [= \$r ${src}] [rel [?splice \$r]]]'
	return code.eval_code('[empty]', prog, 'cx') or { panic('oracle eval failed: ${err.msg()}\n${prog}') }
}

fn maintained(st code.PlanarDeltaState) string {
	rel := cx.Node(cx.Element{
		name:  'rel'
		items: st.result
	})
	return code.render(rel, 'cx') or { panic('render failed: ${err.msg()}') }
}

fn dstate(comp_with_placeholders string, srcs map[string]string, relrows [][]cx.Node) code.PlanarDeltaState {
	mut src := comp_with_placeholders
	for k, v in srcs {
		src = src.replace(k, v)
	}
	prog := cx.parse_program(src) or { panic('comp parse failed: ${err.msg()}\n${src}') }
	return code.planar_delta_init(prog, relrows) or { panic('init failed: ${err}') }
}

fn delta_el(kind string, row_text string) cx.Node {
	r := rows([row_text])
	return cx.Element{
		name:  kind
		items: [r[0]]
	}
}

fn script_pos(n cx.Node) int {
	if n is cx.Element {
		for a in n.attrs {
			if a.name == 'pos' {
				v := a.value
				if v is i64 {
					return int(v)
				}
			}
		}
	}
	return -1
}

fn script_is_recompute(script []cx.Node) bool {
	if script.len != 1 {
		return false
	}
	s0 := script[0]
	return s0 is cx.Element && (s0 as cx.Element).name == 'recompute'
}

// apply_script replays an output ∂ script over the previous relation —
// final coordinates, ascending application order (the vocabulary's
// contract).
fn apply_script(old []cx.Node, script []cx.Node) []cx.Node {
	mut cur := old.clone()
	for d in script {
		el := d as cx.Element
		pos := script_pos(d)
		match el.name {
			'insert' {
				cur.insert(pos, el.items[0])
			}
			'retract' {
				cur.delete(pos)
			}
			'regroup' {
				cur[pos] = el.items[0]
			}
			else {
				panic('unexpected ∂ kind in script: ${el.name}')
			}
		}
	}
	return cur
}

fn assert_script_replays(old []cx.Node, script []cx.Node, st code.PlanarDeltaState) {
	replayed := apply_script(old, script)
	assert replayed.len == st.result.len, '∂ script must reproduce the new relation (len ${replayed.len} vs ${st.result.len})'
	for i, r in replayed {
		assert code.nodes_equal_pub(r, st.result[i]), '∂ script row ${i} diverges from the maintained relation'
	}
}

// ── σ/π — stateless row rules ─────────────────────────────────────────────────

const sigma_comp = '[?for [in \$o %SRC%] [where [= \$o@status "open"]] [= \$v [* \$o@amt 2]] [yield [r id=\$o@id v=\$v]]]'

fn test_sigma_pi_insert_and_retract() {
	mut texts := ['[o id=1 status=open amt=5]', '[o id=2 status=closed amt=3]',
		'[o id=3 status=open amt=4]']
	mut st := dstate(sigma_comp, {
		'%SRC%': '[\$store:source \$s "//o"]'
	}, [rows(texts)])
	assert maintained(st) == oracle(sigma_comp, {
		'%SRC%': seq_text(texts)
	}), 'init: maintained ≡ recompute'
	assert st.result.len == 2

	// insert a σ-passing row — one [insert] at the tail position
	old := st.result.clone()
	s1 := code.planar_delta_apply(mut st, 0, delta_el('insert', '[o id=4 status=open amt=1]')) or {
		panic('apply failed: ${err}')
	}
	texts << '[o id=4 status=open amt=1]'
	assert maintained(st) == oracle(sigma_comp, {
		'%SRC%': seq_text(texts)
	}), 'insert: maintained ≡ recompute'
	assert s1.len == 1 && script_pos(s1[0]) == 2
	assert_script_replays(old, s1, st)

	// insert a σ-pruned row — the empty ∂ script
	old2 := st.result.clone()
	s2 := code.planar_delta_apply(mut st, 0, delta_el('insert', '[o id=5 status=closed amt=9]')) or {
		panic('apply failed: ${err}')
	}
	texts << '[o id=5 status=closed amt=9]'
	assert s2.len == 0, 'a pruned row is an EMPTY ∂ script'
	assert maintained(st) == oracle(sigma_comp, {
		'%SRC%': seq_text(texts)
	}), 'pruned insert: maintained ≡ recompute'
	assert_script_replays(old2, s2, st)

	// retract the first σ-passing row — one [retract] at position 0
	old3 := st.result.clone()
	s3 := code.planar_delta_apply(mut st, 0, delta_el('retract', '[o id=1 status=open amt=5]')) or {
		panic('apply failed: ${err}')
	}
	texts = ['[o id=2 status=closed amt=3]', '[o id=3 status=open amt=4]',
		'[o id=4 status=open amt=1]', '[o id=5 status=closed amt=9]']
	assert maintained(st) == oracle(sigma_comp, {
		'%SRC%': seq_text(texts)
	}), 'retract: maintained ≡ recompute'
	assert s3.len == 1 && script_pos(s3[0]) == 0
	assert_script_replays(old3, s3, st)
}

// ── ⋈ — opposite-side state ───────────────────────────────────────────────────

const join_comp = '[?for [in \$a %A%] [in \$b %B%] [where [= \$a@k \$b@k]] [yield [j a=\$a@id b=\$b@id]]]'

fn test_join_insert_both_sides_and_retract() {
	mut a_texts := ['[a id=1 k=x]', '[a id=2 k=y]']
	mut b_texts := ['[b id=10 k=x]', '[b id=11 k=x]']
	mut st := dstate(join_comp, {
		'%A%': '[\$store:source \$s "//a"]'
		'%B%': '[\$store:source \$s "//b"]'
	}, [rows(a_texts), rows(b_texts)])
	assert maintained(st) == oracle(join_comp, {
		'%A%': seq_text(a_texts)
		'%B%': seq_text(b_texts)
	}), 'init: maintained ≡ recompute'

	// insert on the INNER side — the new row joins the opposite-side state
	// (a2 k=y) and the new frame lands in nested-loop order
	old := st.result.clone()
	s1 := code.planar_delta_apply(mut st, 1, delta_el('insert', '[b id=12 k=y]')) or {
		panic('apply failed: ${err}')
	}
	b_texts << '[b id=12 k=y]'
	assert maintained(st) == oracle(join_comp, {
		'%A%': seq_text(a_texts)
		'%B%': seq_text(b_texts)
	}), 'inner insert: maintained ≡ recompute'
	assert s1.len == 1
	assert_script_replays(old, s1, st)

	// insert on the OUTER side — joins BOTH matching inner rows, a block
	// append at the tail
	old2 := st.result.clone()
	s2 := code.planar_delta_apply(mut st, 0, delta_el('insert', '[a id=3 k=x]')) or {
		panic('apply failed: ${err}')
	}
	a_texts << '[a id=3 k=x]'
	assert maintained(st) == oracle(join_comp, {
		'%A%': seq_text(a_texts)
		'%B%': seq_text(b_texts)
	}), 'outer insert: maintained ≡ recompute'
	assert s2.len == 2, 'the new outer row joins two opposite-side rows'
	assert_script_replays(old2, s2, st)

	// retract an outer row — its whole join block dies
	old3 := st.result.clone()
	s3 := code.planar_delta_apply(mut st, 0, delta_el('retract', '[a id=1 k=x]')) or {
		panic('apply failed: ${err}')
	}
	a_texts = ['[a id=2 k=y]', '[a id=3 k=x]']
	assert maintained(st) == oracle(join_comp, {
		'%A%': seq_text(a_texts)
		'%B%': seq_text(b_texts)
	}), 'outer retract: maintained ≡ recompute'
	assert s3.len == 2
	assert_script_replays(old3, s3, st)
}

// ── γ — group state over monotone deltas ─────────────────────────────────────

const gamma_comp = '[?for [in \$o %SRC%] [= \$v \$o@amt] [group-by \$o@region] [yield [row region=\$key n=\$count total=[\$sum \$group/v]]]]'

fn test_gamma_insert_regroup_new_group_and_retract_recompute() {
	mut texts := ['[o region=east amt=5]', '[o region=west amt=3]', '[o region=east amt=2]']
	mut st := dstate(gamma_comp, {
		'%SRC%': '[\$store:source \$s "//o"]'
	}, [rows(texts)])
	assert maintained(st) == oracle(gamma_comp, {
		'%SRC%': seq_text(texts)
	}), 'init: maintained γ ≡ recompute'
	assert st.result.len == 2

	// insert into an EXISTING group → one [regroup] at the group's ordinal
	old := st.result.clone()
	s1 := code.planar_delta_apply(mut st, 0, delta_el('insert', '[o region=east amt=10]')) or {
		panic('apply failed: ${err}')
	}
	texts << '[o region=east amt=10]'
	assert maintained(st) == oracle(gamma_comp, {
		'%SRC%': seq_text(texts)
	}), 'existing-group insert: maintained γ ≡ recompute'
	assert s1.len == 1
	el1 := s1[0] as cx.Element
	assert el1.name == 'regroup' && script_pos(s1[0]) == 0
	assert_script_replays(old, s1, st)

	// insert a NEW key → one [insert] first-appearing at the end
	old2 := st.result.clone()
	s2 := code.planar_delta_apply(mut st, 0, delta_el('insert', '[o region=north amt=1]')) or {
		panic('apply failed: ${err}')
	}
	texts << '[o region=north amt=1]'
	assert maintained(st) == oracle(gamma_comp, {
		'%SRC%': seq_text(texts)
	}), 'new-group insert: maintained γ ≡ recompute'
	assert s2.len == 1
	el2 := s2[0] as cx.Element
	assert el2.name == 'insert' && script_pos(s2[0]) == 2
	assert_script_replays(old2, s2, st)

	// retract reaching γ — OUTSIDE the monotone rule: the honest
	// [recompute] marker, state rebuilt, still ≡ recompute
	s3 := code.planar_delta_apply(mut st, 0, delta_el('retract', '[o region=west amt=3]')) or {
		panic('apply failed: ${err}')
	}
	texts = ['[o region=east amt=5]', '[o region=east amt=2]', '[o region=east amt=10]',
		'[o region=north amt=1]']
	assert script_is_recompute(s3), 'γ retract answers [recompute], never a wrong ∂'
	r3 := s3[0] as cx.Element
	mut reason := ''
	for a in r3.attrs {
		if a.name == 'reason' {
			v := a.value
			if v is string {
				reason = v
			}
		}
	}
	assert reason.contains('monotone'), 'the marker names the rule: ${reason}'
	assert maintained(st) == oracle(gamma_comp, {
		'%SRC%': seq_text(texts)
	}), 'γ retract: rebuilt state ≡ recompute'
}

// A join-fed γ where an insert moves an existing key's FIRST APPEARANCE
// across another group's — group order is first-appearance (L94), so the
// in-place rule cannot hold and the answer is [recompute], loud.
const gamma_join_comp = '[?for [in \$a %A%] [in \$b %B%] [where [= \$a@k \$b@k]] [group-by \$b@g] [yield [row g=\$key n=\$count]]]'

fn test_gamma_first_appearance_reorder_recomputes() {
	a_texts := ['[a id=1 k=x]', '[a id=2 k=y]']
	mut b_texts := ['[b id=10 k=y g=L]', '[b id=11 k=y g=K]']
	mut st := dstate(gamma_join_comp, {
		'%A%': '[\$store:source \$s "//a"]'
		'%B%': '[\$store:source \$s "//b"]'
	}, [rows(a_texts), rows(b_texts)])
	assert maintained(st) == oracle(gamma_join_comp, {
		'%A%': seq_text(a_texts)
		'%B%': seq_text(b_texts)
	}), 'init: maintained γ ≡ recompute'
	assert st.result.len == 2 // groups L, K (first appearance in the a2 block)

	// b3 joins a1 (an EARLIER outer block) with the existing key K — K's
	// first appearance jumps ahead of L's → group order flips → recompute.
	s := code.planar_delta_apply(mut st, 1, delta_el('insert', '[b id=12 k=x g=K]')) or {
		panic('apply failed: ${err}')
	}
	b_texts << '[b id=12 k=x g=K]'
	assert script_is_recompute(s), 'a first-appearance reorder is answered [recompute]'
	assert maintained(st) == oracle(gamma_join_comp, {
		'%A%': seq_text(a_texts)
		'%B%': seq_text(b_texts)
	}), 'reorder: rebuilt state ≡ recompute'
}

