// ── incremental sub-fragment membership — the loud exclusions ────────────────

fn excl(src string) string {
	prog := cx.parse_program(src) or { panic('parse failed: ${err.msg()}\n${src}') }
	if x := code.planar_incremental_membership(prog) {
		return x.reason
	}
	return ''
}

fn test_exclusion_tau() {
	r := excl('[?for [in \$o [\$store:source \$s "//o"]] [order-by \$o@k] [yield \$o]]')
	assert r.contains('τ'), r
	assert r.contains('recompute'), r
}

fn test_exclusion_lambda() {
	r := excl('[?for [in \$o [\$store:source \$s "//o"]] [take 3] [yield \$o]]')
	assert r.contains('λ'), r
}

fn test_exclusion_output_shape() {
	r := excl('[?for-map [in \$o [\$store:source \$s "//o"]] [yield-map \$o@k \$o@v]]')
	assert r.contains('SEQUENCE relation'), r
}

fn test_exclusion_partial_predicate() {
	// Ordered comparison is STRICT (errs on non-numeric) — unproven total,
	// so the err-totality rule forces recompute-only.
	r := excl('[?for [in \$o [\$store:source \$s "//o"]] [where [> \$o@amt 3]] [yield \$o]]')
	assert r.contains('not established total'), r
}

fn test_exclusion_chained_gamma() {
	r := excl('[?for [in \$o [\$store:source \$s "//o"]] [group-by \$o@a] [group-by \$o@b] [yield \$key]]')
	assert r.contains('chained γ') || r.contains('post-γ'), r
}

fn test_exclusion_post_gamma_clause() {
	r := excl('[?for [in \$o [\$store:source \$s "//o"]] [group-by \$o@a] [where [= \$key "x"]] [yield \$key]]')
	assert r.contains('post-γ'), r
}

fn test_exclusion_non_planar() {
	r := excl('[?for [in \$x \$data] [yield \$x]]')
	assert r.contains('not a planar member'), r
}

fn test_member_gamma_total_pipeline() {
	prog := cx.parse_program('[?for [in \$o [\$store:source \$s "//o"]] [where [= \$o@status "open"]] [= \$v \$o@amt] [group-by \$o@region] [yield [row region=\$key total=[\$sum \$group/v]]]]') or {
		panic('parse failed: ${err.msg()}')
	}
	if x := code.planar_incremental_membership(prog) {
		assert false, 'expected maintainable, got: ${x.reason}'
	}
}

// ── source: vcx/tests/planar_membership_test.v ──
// planar_membership_test.v — the six-point planar-fragment membership
// battery (code.md §7.8, stream-2 ruling L95; W3 of the I5 stream-2 ledger).
//
// The checker is the shared foundation for the planar consumers (plan-form /
// plan address at W4, quoted store queries at W6, live modes at stream 3);
// this battery pins every point's refusal (typed E_NOT_PLANAR, the message
// naming the violated point) and the member set (incl. the ruled M5 worked
// example and the erased execution hints).

fn pm_parse(src string) cx.ProgramNode {
	prog := cx.parse_program(src) or { panic('parse failed: ${err.msg()}\n${src}') }
	return prog
}

fn pm_check(src string) ?code.PlanarRefusal {
	return code.planar_membership(pm_parse(src))
}

fn pm_assert_member(src string) {
	if r := pm_check(src) {
		assert false, 'expected MEMBER, got refusal point ${r.point}: ${r.reason}\n${src}'
	}
}

fn pm_assert_refused(src string, point int) code.PlanarRefusal {
	if r := pm_check(src) {
		assert r.point == point, 'expected refusal at point ${point}, got point ${r.point}: ${r.reason}\n${src}'
		return r
	}
	assert false, 'expected refusal at point ${point}, got MEMBER\n${src}'
	return code.PlanarRefusal{}
}

