// The ruled M5 worked example (planar_algebra.md): source-ref generator,
// correlated unnest, pure binder/key/yield, group-by aggregate.
fn test_member_m5_revenue_by_region() {
	pm_assert_member('[?for [in \$o [\$store:source \$s "//order"]] [in \$l \$o/line]
		[= \$r [* \$l@qty \$l@price]]
		[group-by \$o/customer/@region]
		[yield [row region=\$key revenue=[\$sum \$group/r]]]]')
}

fn test_member_journal_source_generator() {
	pm_assert_member('[?for [in \$e [\$journal:source \$j "orders"]] [yield \$e/event]]')
}

// A nested planar comprehension as a generator source — correlated: its own
// generator reads the OUTER comprehension's binding.
fn test_member_nested_planar_correlated() {
	pm_assert_member('[?for [in \$o [\$store:source \$s "//o"]]
		[in \$x [?for [in \$l \$o/line] [yield \$l]]]
		[yield \$x]]')
}

// Execution hints are members (point 6: ERASED by planar consumers).
fn test_member_hints_erased() {
	pm_assert_member('[?for [in \$o [\$store:source \$s "//o"]] [par] [ordered] [yield \$o]]')
	pm_assert_member('[?for [in \$o [\$store:source \$s "//o"]] [lazy] [yield \$o]]')
}

// A bounded pure computed source with no free names is a self-contained root.
fn test_member_bounded_range_source() {
	pm_assert_member('[?for [in \$x [\$range 1 10]] [where [> \$x 3]] [order-by \$x desc] [limit 3] [yield \$x]]')
}

// The full closed clause vocabulary in one comprehension.
fn test_member_full_vocabulary() {
	pm_assert_member('[?for [in \$o [\$store:source \$s "//o"]]
		[= \$v \$o@v] [where [> \$v 1]] [order-by \$v] [group-by \$v]
		[limit 10] [take 5] [drop 1]
		[yield [g k=\$key n=\$count]]]')
}

// for-array / for-map heads are members (point 1's closed head set).
fn test_member_outer_forms() {
	pm_assert_member('[?for-array [in \$o [\$store:source \$s "//o"]] [yield-array \$o]]')
	pm_assert_member('[?for-map [in \$o [\$store:source \$s "//o"]] [yield-map \$o@k \$o@v]]')
}

