	assert r.reason.contains('ambient'), r.reason
}

// A CXPath value source reads the ambient document.
fn test_refuse_ambient_path_source() {
	r := pm_assert_refused('[?for [in \$x //user] [yield \$x]]', 3)
	assert r.reason.contains('ambient'), r.reason
}

// An enclosing-scope binding as source: the root is not named.
fn test_refuse_ambient_binding_source() {
	r := pm_assert_refused('[?for [in \$x \$data] [yield \$x]]', 3)
	assert r.reason.contains('data'), r.reason
}

// Correlated sources over EARLIER clause bindings stay members — the same
// spelling referencing a LATER binding is ambient.
fn test_refuse_forward_reference_source() {
	pm_assert_refused('[?for [in \$l \$o/line] [in \$o [\$store:source \$s "//o"]] [yield \$l]]',
		3)
}

// The unbounded generator.
fn test_refuse_open_end_range() {
	r := pm_assert_refused('[?for [in \$x [\$range 1 *]] [take 5] [yield \$x]]', 3)
	assert r.reason.contains('unbounded'), r.reason
}

// An impure computed source is an unnamed external root.
fn test_refuse_impure_source() {
	pm_assert_refused('[?for [in \$x [\$range 1 [\$random-int]]] [yield \$x]]', 3)
}

// A nested NON-planar comprehension as source refuses through the recursion.
fn test_refuse_nested_non_planar_source() {
	pm_assert_refused('[?for [in \$x [?for [in \$y \$ambient] [yield \$y]]] [yield \$x]]',
		3)
}

// ── point 4: purity ───────────────────────────────────────────────────────────

fn test_refuse_impure_predicate() {
	r := pm_assert_refused('[?for [in \$o [\$store:source \$s "//o"]] [where [> [\$random] 0.5]] [yield \$o]]',
		4)
	assert r.reason.contains('random'), r.reason
}

fn test_refuse_impure_yield() {
	pm_assert_refused('[?for [in \$o [\$store:source \$s "//o"]] [yield [\$now]]]',
		4)
}

fn test_refuse_impure_binder() {
	pm_assert_refused('[?for [in \$o [\$store:source \$s "//o"]] [= \$t [\$now]] [yield \$o]]',
		4)
}

fn test_refuse_impure_group_key() {
	pm_assert_refused('[?for [in \$o [\$store:source \$s "//o"]] [group-by [\$random]] [yield \$key]]',
		4)
}

// The yield-map VALUE node is walked too (the W2 ONE-walk lesson).
fn test_refuse_impure_yield_map_value() {
	pm_assert_refused('[?for-map [in \$o [\$store:source \$s "//o"]] [yield-map \$o@k [\$now]]]',
		4)
}

// ── point 5: no [?eval] / [?with-scope] ───────────────────────────────────────

fn test_refuse_eval_in_yield() {
	r := pm_assert_refused('[?for [in \$o [\$store:source \$s "//o"]] [yield [?eval \$o]]]',
		5)
	assert r.reason.contains('eval'), r.reason
}

fn test_refuse_with_scope_in_binder() {
	// [?with-scope] is body-derived in the purity tables (pure-flow), so the
	// by-name point-5 check is the only thing standing — the exact reason it
	// exists in addition to point 4.
	r := pm_assert_refused("[?for [in \$o [\$store:source \$s '//o']] [= \$v [?with-scope {} \$o]] [yield \$v]]",
		5)
	assert r.reason.contains('with-scope'), r.reason
}

// ── point 6: order-observers ──────────────────────────────────────────────────

fn test_refuse_position_in_yield() {
	r := pm_assert_refused('[?for [in \$o [\$store:source \$s "//o"]] [yield [n pos=\$_position v=\$o]]]',
		6)
	assert r.reason.contains('_position'), r.reason
}

// ── #770 (RULED (a) 2026-08-10): λ-count purity + the ambient-read cousin ────

fn test_member_pure_computed_lambda_count() {
	// A pure computed count is harmless and useful — stays a member.
	pm_assert_member('[?for [in \$o [\$store:source \$s "//o"]] [take [* 2 2]] [yield \$o]]')
}

fn test_member_free_name_lambda_count() {
	// A free-name count is a §7.9 plan parameter — stays a member.
	pm_assert_member('[?for [in \$o [\$store:source \$s "//o"]] [take \$n] [yield \$o]]')
}

fn test_refuse_impure_lambda_count() {
	// Point 4's enumeration reaches λ counts (the #770 gap: an impure count
	// broke the determinism guarantee while passing the test).
	r := pm_assert_refused('[?for [in \$o [\$store:source \$s "//o"]] [take [\$random]] [yield \$o]]',
		4)
	assert r.reason.contains('random'), r.reason
	assert r.reason.contains('take'), r.reason
}

fn test_refuse_ambient_read_in_predicate() {
	// The cousin: point 3's ambient exclusion is not source-slot-scoped — a
	// document-context read in a [where] predicate is a dependency the
	// source set cannot name.
	r := pm_assert_refused('[?for [in \$o [\$store:source \$s "//o"]] [where [> [\$count //order] 0]] [yield \$o]]',
		3)
	assert r.reason.contains('ambient document'), r.reason
}

fn test_refuse_ambient_read_in_yield() {
	pm_assert_refused('[?for [in \$o [\$store:source \$s "//o"]] [yield [row o=\$o total=[\$count //order]]]]',
		3)
}

fn test_refuse_ambient_read_in_group_key() {
	pm_assert_refused('[?for [in \$o [\$store:source \$s "//o"]] [group-by [\$count //region]] [yield \$key]]',
		3)
}

fn test_refuse_ambient_read_in_lambda_count() {
	pm_assert_refused('[?for [in \$o [\$store:source \$s "//o"]] [take [\$count //order]] [yield \$o]]',
		3)
}

fn test_refuse_ambient_read_nested_in_computed_source() {
	// Nested inside a COMPUTED source expression (the top-level PathExpr
	// source already had its own refusal).
	pm_assert_refused('[?for [in \$o [\$store:source \$s "//o"]] [in \$x [\$concat \$o/line //extra]] [yield \$x]]',
		3)
}

fn test_member_binding_rooted_paths_unaffected() {
	// Binding-rooted paths are frame-local reads — the ruled carve-out.
	pm_assert_member('[?for [in \$o [\$store:source \$s "//order"]]
		[where [= \$o/status "open"]]
		[order-by \$o/customer/@region]
		[yield \$o/line]]')
}

// ── the typed error value ─────────────────────────────────────────────────────

fn test_refusal_err_value_shape() {
	r := pm_assert_refused('[?for [in \$x \$data] [yield \$x]]', 3)
	errn := code.planar_refusal_err(r)
	assert errn is cx.Element, 'err value must be an element'
	if errn is cx.Element {
		assert errn.name == 'err'
		mut code_attr := ''
		mut msg_attr := ''
		for a in errn.attrs {
			if a.name == 'code' {
				code_attr = cx.scalar_value_str_public(a.value)
			}
			if a.name == 'message' {
				msg_attr = cx.scalar_value_str_public(a.value)
			}
		}
		assert code_attr == 'cx-err:CXER0120', 'code: ${code_attr}'
		assert msg_attr.starts_with('comprehension is not planar: '), 'canonical message (§9.5.1): ${msg_attr}'
		assert msg_attr.contains('membership point 3'), 'message names the violated point: ${msg_attr}'
	}
}

// ── source: vcx/tests/planar_plan_test.v ──
// planar_plan_test.v — the canonical plan form + plan address battery
// (code.md §7.9, stream-2 ruling L93; W4 of the I5 stream-2 ledger).
//
// The done-when pair cases: two spellings → ONE plan address, while the
// `$x`-vs-`$y` E1 (text) distinction is preserved below the plan tier.
// Plus: hint erasure, the ruled limit≡take collapse, λ literal
// composition, explicit-asc defaults, parameter (free-name) sensitivity,
// nested-comprehension recursion, membership gating (CXER0120), and the
// address's distinct-token shape.

const pp_m5 = '[?for [in \$o [\$store:source \$s "//order"]] [in \$l \$o/line]
	[= \$r [* \$l@qty \$l@price]]
	[group-by \$o/customer/@region]
	[yield [row region=\$key revenue=[\$sum \$group/r]]]]'

// The M5 worked example alpha-respelled ($o→$ord, $l→$ln, $r→$rev).
const pp_m5_respelled = '[?for [in \$ord [\$store:source \$s "//order"]] [in \$ln \$ord/line]
	[= \$rev [* \$ln@qty \$ln@price]]
	[group-by \$ord/customer/@region]
	[yield [row region=\$key revenue=[\$sum \$group/rev]]]]'

fn pp_addr(src string) string {
	return code.cx_plan_address(src) or { panic('plan address failed: ${err.msg()}\n${src}') }
}

fn pp_assert_same(a string, b string) {
	aa := pp_addr(a)
	ba := pp_addr(b)
	assert aa == ba, 'expected ONE plan address, got\n  ${aa}\n  ${ba}\nfor\n${a}\n-- vs --\n${b}'
}

fn pp_assert_distinct(a string, b string) {
	aa := pp_addr(a)
	ba := pp_addr(b)
	assert aa != ba, 'expected DISTINCT plan addresses, both ${aa}\nfor\n${a}\n-- vs --\n${b}'
}

// ── the address token ─────────────────────────────────────────────────────────

fn test_plan_address_is_a_distinct_token() {
	addr := pp_addr(pp_m5)
	assert addr.starts_with('plan:sha2-256:'), addr
	// never a document address: the tagged-address reader refuses the
	// `plan` lead (unregistered algorithm), so the token can never be
	// mistaken for, or used as, a content address.
	cx.cx_parse_tagged_address(addr) or {
		assert err.msg().contains('CXER0131'), err.msg()
		return
	}
	assert false, 'the tagged-address reader must refuse a plan: token'
}

// ── the done-when pair case: alpha respelling ─────────────────────────────────

fn test_pair_alpha_respelling_shares_one_address() {
	pp_assert_same(pp_m5, pp_m5_respelled)
}

fn test_pair_alpha_e1_distinction_preserved() {
	// E1 is TEXT identity (name-sensitive): the two spellings stay two
	// E1 identities below the shared plan tier — and the plan encodings
	// (not just the addresses) are byte-identical (equality⟺byte-identity).
	assert pp_m5 != pp_m5_respelled
	fa := code.cx_plan_form(pp_m5) or { panic(err.msg()) }
	fb := code.cx_plan_form(pp_m5_respelled) or { panic(err.msg()) }
	assert fa == fb, 'alpha-respellings must share ONE canonical encoding'
}

// A parameter (free name) rename is NOT alpha-equivalence: the source-ref
// handle `$s` arrives from enclosing scope — renaming it changes the plan.
fn test_parameter_rename_changes_the_address() {
	a := '[?for [in \$o [\$store:source \$s "//o"]] [yield \$o]]'
	b := '[?for [in \$o [\$store:source \$t "//o"]] [yield \$o]]'
	pp_assert_distinct(a, b)
}

// ── hint erasure ──────────────────────────────────────────────────────────────

fn test_hints_do_not_split_the_address() {
	bare := '[?for [in \$o [\$store:source \$s "//o"]] [where [> \$o@v 1]] [yield \$o]]'
	hinted := '[?for [in \$o [\$store:source \$s "//o"]] [par] [where [> \$o@v 1]] [ordered] [yield \$o]]'
	lazy_hinted := '[?for [in \$o [\$store:source \$s "//o"]] [where [> \$o@v 1]] [lazy] [yield \$o]]'
	par_width := '[?for [in \$o [\$store:source \$s "//o"]] [par 4] [where [> \$o@v 1]] [yield \$o]]'
	pp_assert_same(bare, hinted)
	pp_assert_same(bare, lazy_hinted)
	pp_assert_same(bare, par_width)
}

// ── the λ tail ────────────────────────────────────────────────────────────────

fn test_limit_take_collapse() {
	a := '[?for [in \$o [\$store:source \$s "//o"]] [limit 5] [yield \$o]]'
	b := '[?for [in \$o [\$store:source \$s "//o"]] [take 5] [yield \$o]]'
	pp_assert_same(a, b)
}

fn test_lambda_literal_composition() {
	// consecutive literal drops SUM
	pp_assert_same('[?for [in \$o [\$store:source \$s "//o"]] [drop 1] [drop 2] [yield \$o]]',
		'[?for [in \$o [\$store:source \$s "//o"]] [drop 3] [yield \$o]]')
	// consecutive literal takes MIN
	pp_assert_same('[?for [in \$o [\$store:source \$s "//o"]] [take 5] [take 3] [yield \$o]]',
		'[?for [in \$o [\$store:source \$s "//o"]] [take 3] [yield \$o]]')
	// a literal [drop 0] is erased
	pp_assert_same('[?for [in \$o [\$store:source \$s "//o"]] [drop 0] [yield \$o]]',
		'[?for [in \$o [\$store:source \$s "//o"]] [yield \$o]]')
	// mixed spelling order: λ clauses are position-independent relation
	// truncations (drops before takes in the canonical tail)
	pp_assert_same('[?for [in \$o [\$store:source \$s "//o"]] [take 3] [drop 1] [yield \$o]]',
		'[?for [in \$o [\$store:source \$s "//o"]] [drop 1] [take 3] [yield \$o]]')
}

fn test_lambda_distinct_counts_stay_distinct() {
	pp_assert_distinct('[?for [in \$o [\$store:source \$s "//o"]] [take 3] [yield \$o]]',
		'[?for [in \$o [\$store:source \$s "//o"]] [take 4] [yield \$o]]')
	// [take 0] is meaningful (empty relation), not erased
	pp_assert_distinct('[?for [in \$o [\$store:source \$s "//o"]] [take 0] [yield \$o]]',
		'[?for [in \$o [\$store:source \$s "//o"]] [yield \$o]]')
}

fn test_lambda_non_literal_counts_stay_unfused() {
	// a non-literal count is plan structure (a parameter read) — distinct
	// from any literal, and the parameter name is E1-verbatim.
	a := '[?for [in \$o [\$store:source \$s "//o"]] [take \$n] [yield \$o]]'
	b := '[?for [in \$o [\$store:source \$s "//o"]] [take 3] [yield \$o]]'
	c := '[?for [in \$o [\$store:source \$s "//o"]] [take \$m] [yield \$o]]'
	pp_assert_distinct(a, b)
	pp_assert_distinct(a, c)
	// a literal run BROKEN by a non-literal must not fold across it:
	// [take 5] [take $n] [take 3] ≠ [take 3] [take $n] [take 5]... but the
	// two literal singleton runs (5, then 3) keep their surface order.
	d := '[?for [in \$o [\$store:source \$s "//o"]] [take 5] [take \$n] [take 3] [yield \$o]]'
	e := '[?for [in \$o [\$store:source \$s "//o"]] [take 3] [take \$n] [take 5] [yield \$o]]'
	pp_assert_distinct(d, e)
}

// ── explicit defaults ─────────────────────────────────────────────────────────

fn test_order_by_asc_default_is_explicit() {
	pp_assert_same('[?for [in \$o [\$store:source \$s "//o"]] [order-by \$o@v] [yield \$o]]',
		'[?for [in \$o [\$store:source \$s "//o"]] [order-by \$o@v asc] [yield \$o]]')
	pp_assert_distinct('[?for [in \$o [\$store:source \$s "//o"]] [order-by \$o@v] [yield \$o]]',
		'[?for [in \$o [\$store:source \$s "//o"]] [order-by \$o@v desc] [yield \$o]]')
}

// ── clause order is meaning ───────────────────────────────────────────────────

fn test_semantic_clause_order_is_preserved() {
	// σ before vs after a barrier is a DIFFERENT plan (the plan tier does
	// no reordering an err could observe; σ-pushdown is an L96 executor
	// rewrite, never a plan-address move).
	a := '[?for [in \$o [\$store:source \$s "//o"]] [where [> \$o@v 1]] [order-by \$o@v] [yield \$o]]'
	b := '[?for [in \$o [\$store:source \$s "//o"]] [order-by \$o@v] [where [> \$o@v 1]] [yield \$o]]'
	pp_assert_distinct(a, b)
}

// ── γ columns and nesting ─────────────────────────────────────────────────────

fn test_gamma_columns_encode_by_name() {
	// $key/$count/$group are operator-defined columns: respelling the
	// CLAUSE binds collapses, while the γ columns pass through by name.
	a := '[?for [in \$o [\$store:source \$s "//o"]] [group-by \$o@r] [yield [g k=\$key n=\$count]]]'
	b := '[?for [in \$x [\$store:source \$s "//o"]] [group-by \$x@r] [yield [g k=\$key n=\$count]]]'
	pp_assert_same(a, b)
}

fn test_nested_comprehension_normalizes_recursively() {
	a := '[?for [in \$o [\$store:source \$s "//o"]] [in \$x [?for [in \$l \$o/line] [yield \$l]]] [yield \$x]]'
	b := '[?for [in \$o [\$store:source \$s "//o"]] [in \$x [?for [in \$q \$o/line] [yield \$q]]] [yield \$x]]'
	pp_assert_same(a, b)
}

// ── membership gating (the checker's first runtime consumer) ──────────────────

fn test_non_member_refused_typed() {
	// ambient-document generator (point 3)
	mut refused := false
	code.cx_plan_address('[?for [user] [yield 1]]') or {
		assert err.msg().contains('CXER0120'), err.msg()
		assert err.msg().contains('point 3'), err.msg()
		refused = true
		''
	}
	assert refused, 'ambient-doc generator must refuse plan-form entry'
	// a non-comprehension refuses at point 1
	refused = false
	code.cx_plan_address('[?let [= \$x 1] \$x]') or {
		assert err.msg().contains('CXER0120'), err.msg()
		refused = true
		''
	}
	assert refused, 'non-comprehension must refuse'
}

fn test_malformed_source_is_not_cxer0120() {
	code.cx_plan_address('[?for [in $o') or {
		assert err.msg().contains('CXER4100'), err.msg()
		assert !err.msg().contains('CXER0120'), err.msg()
		return
	}
	assert false, 'malformed source must error'
}

// point 5 now reaches λ counts ("anywhere in clause expressions" — the W4
// checker-gap fix).
fn test_membership_point5_reaches_lambda_counts() {
	code.cx_plan_address('[?for [in \$o [\$store:source \$s "//o"]] [take [?eval "1"]] [yield \$o]]') or {
		assert err.msg().contains('CXER0120'), err.msg()
		assert err.msg().contains('point 5'), err.msg()
		assert err.msg().contains('take'), err.msg()
		return
	}
	assert false, '[?eval] inside a [take] count must refuse at point 5'
}

// ── encoding round-trip stability ─────────────────────────────────────────────

// #772 rider (the W7-audit continuation): the PLAN tier had the same
// predicate holes the Tier-2 tier had — attr KIND (existence ≡ absence)
// and the type-test TYPE NAME never entered the plan encoding, so two
// different queries shared one plan address (a caching identity: false
// sharing serves wrong cached results).

fn test_plan_predicate_attr_kind_distinct() {
	a := pp_addr('[?for [in \$o [\$store:source \$s "//o"]] [where [\$count \$o/line[@k]]] [yield \$o]]')
	b := pp_addr('[?for [in \$o [\$store:source \$s "//o"]] [where [\$count \$o/line[@!k]]] [yield \$o]]')
	assert a != b, 'attr existence vs absence predicates are different plans'
}

fn test_plan_predicate_type_test_distinct() {
	a := pp_addr('[?for [in \$o [\$store:source \$s "//o"]] [where [\$count \$o/line[@age::int]]] [yield \$o]]')
	b := pp_addr('[?for [in \$o [\$store:source \$s "//o"]] [where [\$count \$o/line[@age::str]]] [yield \$o]]')
	assert a != b, 'predicate type tests are different plans'
}

fn test_plan_form_is_deterministic() {
	f1 := code.cx_plan_form(pp_m5) or { panic(err.msg()) }
	f2 := code.cx_plan_form(pp_m5) or { panic(err.msg()) }
	assert f1 == f2
	assert f1.starts_with('plan1')
}

// ── source: vcx/tests/planar_rewrite_test.v ──
// planar_rewrite_test.v — the L96 equivalence-set battery (W5 of the I5
// stream-2 ledger): σ-pushdown below τ, σ/σ commutation, σ-placement, π
// pruning — every rewrite applied is verified EQUIVALENT by evaluating the
// original and rewritten comprehensions through the LIVE engine and
// comparing rendered results (incl. the err cases); every decline carries
// its err-rule / order-barrier reason.

struct RwCase {
	comp   cx.ProgramForComp
	report code.PlanarRewriteReport
}

fn rw(src string) RwCase {
	prog := cx.parse_program(src) or { panic('parse failed: ${err.msg()}\n${src}') }
	comp, report := code.planar_rewrite(prog) or { panic('rewrite refused: ${err.msg()}\n${src}') }
	return RwCase{
		comp:   comp
		report: report
	}
}

// rw_eval evaluates a program source through the live engine (empty input
// doc) and returns the rendered output.
fn rw_eval(src string) string {
	return code.eval_code('[empty]', src, 'cx') or { 'THROWN: ${err.msg()}' }
}

// rw_assert_equiv asserts the rewritten comprehension evaluates
// byte-identically to the original (the pushdown equivalence pair).
fn rw_assert_equiv(src string, c RwCase) {
	rewritten := code.program_node_to_source(cx.ProgramNode(c.comp))
	orig_out := rw_eval(src)
	rw_out := rw_eval(rewritten)
	assert orig_out == rw_out, 'rewrite changed the result!\noriginal:  ${src}\n→ ${orig_out}\nrewritten: ${rewritten}\n→ ${rw_out}'
}

fn rw_kinds(entries []code.PlanarRewriteEntry) []string {
	mut out := []string{}
	for e in entries {
		out << e.kind
	}
	return out
}

fn rw_decline_kinds(entries []code.PlanarRewriteDecline) []string {
	mut out := []string{}
	for e in entries {
		out << e.kind
	}
	return out
}

// ── applied rewrites, equivalence-verified live ───────────────────────────────

fn test_sigma_pushdown_below_tau_applied() {
	src := '[?for [in \$x [\$range 1 6]] [order-by \$x desc] [where [= \$x 4]] [yield \$x]]'
	c := rw(src)
	assert 'sigma-pushdown-below-tau' in rw_kinds(c.report.applied), c.report.str()
	// the σ now precedes the τ in the rewritten clause list
	mut widx := -1
	mut oidx := -1
	for i, cl in c.comp.clauses {
		if cl.kind == .filter {
			widx = i
		}
		if cl.kind == .order_by {
			oidx = i
		}
	}
	assert widx >= 0 && oidx >= 0 && widx < oidx, 'σ did not move below τ'
	rw_assert_equiv(src, c)
}

fn test_sigma_placement_across_independent_generator() {
	src := '[?for [in \$a [\$range 1 3]] [in \$b [\$range 1 3]] [where [= \$a 2]] [yield [p \$a \$b]]]'
	c := rw(src)
	assert 'sigma-placement' in rw_kinds(c.report.applied), c.report.str()
	// σ now sits between the two generators
	assert c.comp.clauses[1].kind == .filter, 'σ did not hoist above the independent generator'
	rw_assert_equiv(src, c)
}

fn test_sigma_sigma_commutation() {
	// the second σ is independent of the first and both are total — it
	// commutes past the first σ and the independent generator boundary it
	// can reach.
	src := '[?for [in \$a [\$range 1 4]] [in \$b [\$range 1 2]] [where [= \$b 1]] [where [= \$a 3]] [yield [p \$a \$b]]]'
	c := rw(src)
	assert 'sigma-commutation' in rw_kinds(c.report.applied), c.report.str()
	rw_assert_equiv(src, c)
}

fn test_pi_prune_unread_total_extension() {
	src := '[?for [in \$x [\$range 1 3]] [= \$y \$x] [= \$z "unused"] [yield \$y]]'
	c := rw(src)
	assert 'pi-prune-extend' in rw_kinds(c.report.applied), c.report.str()
	// the unread extension is gone
	mut bindings := 0
	for cl in c.comp.clauses {
		if cl.kind == .binding {
			bindings++
		}
	}
	assert bindings == 1, 'expected exactly the read [= \$y …] to survive'
	rw_assert_equiv(src, c)
}

// the err-case equivalence pair: an applied pushdown must preserve the err
// the yield raises on a surviving frame.
fn test_pushdown_preserves_yield_err() {
	src := '[?for [in \$x [\$range 1 6]] [order-by \$x desc] [where [= \$x 4]] [yield [\$div 1 [- \$x 4]]]]'
	c := rw(src)
	assert 'sigma-pushdown-below-tau' in rw_kinds(c.report.applied), c.report.str()
	orig_out := rw_eval(src)
	assert orig_out.contains('err') || orig_out.contains('THROWN'), 'expected the pair to err: ${orig_out}'
	rw_assert_equiv(src, c)
}

// ── the err rule: total-vs-partial negatives ──────────────────────────────────

fn test_partial_predicate_declines_pushdown() {
	// [>] is strict — non-numeric operands err — so the predicate is not
	// established total and σ stays put.
	src := '[?for [in \$x [\$range 1 6]] [order-by \$x desc] [where [> \$x 3]] [yield \$x]]'
	c := rw(src)
	assert c.report.applied.len == 0, c.report.str()
	assert 'sigma-pushdown-below-tau' in rw_decline_kinds(c.report.declined), c.report.str()
	mut reason := ''
	for d in c.report.declined {
		if d.kind == 'sigma-pushdown-below-tau' {
			reason = d.reason
		}
	}
	assert reason.contains('not established total'), reason
	// unchanged clause order: σ still after τ
	assert c.comp.clauses[1].kind == .order_by && c.comp.clauses[2].kind == .filter
}

fn test_partial_order_key_declines_pushdown() {
	// total predicate, but the τ key ([$mod …] not whitelisted) is
	// unproven — pushing σ below would destroy key errs on dropped frames.
	src := '[?for [in \$x [\$range 1 6]] [order-by [\$mod \$x 3]] [where [= \$x 4]] [yield \$x]]'
	c := rw(src)
	assert c.report.applied.len == 0, c.report.str()
	mut reason := ''
	for d in c.report.declined {
		if d.kind == 'sigma-pushdown-below-tau' {
			reason = d.reason
		}
	}
	assert reason.contains('order-by key'), c.report.str()
}

fn test_pi_prune_declines_partial_extension() {
	// $z is unread and its expression can err (division). Under §7.2's
	// guard-scoped err rule a binder err is INERT (the live output below
	// pins that — no comp err), so pruning would be sound today; the
	// analyzer still declines CONSERVATIVELY absent a totality proof (the
	// gate may relax with stream-16 inference — the decline reason says
	// so).
	src := '[?for [in \$x [\$range 0 2]] [= \$z [\$div 1 \$x]] [yield \$x]]'
	c := rw(src)
	assert 'pi-prune-extend' !in rw_kinds(c.report.applied), c.report.str()
	assert 'pi-prune-extend' in rw_decline_kinds(c.report.declined), c.report.str()
	// ground truth: the unread binder err is inert — the comprehension
	// yields its rows (the conservative decline changes nothing).
	out := rw_eval(src)
	assert out.contains('0') && out.contains('2'), out
	assert !out.contains('THROWN'), out
}

// ── order-barrier negatives ───────────────────────────────────────────────────

fn test_sigma_never_crosses_nested_lambda() {
	// the generator source is a nested comprehension carrying [take 5] —
	// pushing the outer σ inside would filter BEFORE the truncation (a
	// different relation: 7 survives inside-first, is truncated away
	// outside-first). Declined with the λ-barrier reason; the naive result
	// (empty) stands.
	src := '[?for [in \$y [?for [in \$x [\$range 1 10]] [take 5] [yield \$x]]] [where [= \$y 7]] [yield \$y]]'
	c := rw(src)
	assert 'sigma-pushdown-into-source' in rw_decline_kinds(c.report.declined), c.report.str()
	mut reason := ''
	for d in c.report.declined {
		if d.kind == 'sigma-pushdown-into-source' {
			reason = d.reason
		}
	}
	assert reason.contains('λ') || reason.contains('order-fixing'), reason
	assert c.report.applied.len == 0, c.report.str()
	rw_assert_equiv(src, c) // unchanged — both spellings ARE the original
	// ground truth: the wrong rewrite would answer `7`; the honest answer
	// is empty.
	out := rw_eval(src)
	assert !out.contains('7'), 'σ-across-λ ground truth violated: ${out}'
}

fn test_gamma_barrier_blocks_hoist() {
	// a σ after [group-by] filters GROUP frames ($count over the γ
	// bindings) — never hoisted above γ.
	src := '[?for [in \$x [\$range 1 6]] [group-by [= \$x 3]] [where [= \$count 5]] [yield \$key]]'
	c := rw(src)
	for e in c.report.applied {
		assert e.kind != 'sigma-pushdown-below-tau' && e.kind != 'sigma-placement', c.report.str()
	}
	// σ stays after γ
	mut gidx := -1
	mut widx := -1
	for i, cl in c.comp.clauses {
		if cl.kind == .group_by {
			gidx = i
		}
		if cl.kind == .filter {
			widx = i
		}
	}
	assert gidx >= 0 && widx > gidx, 'σ must stay after the γ barrier'
}

// ── membership gating and report rendering ────────────────────────────────────

fn test_rewrite_refuses_non_member() {
	prog := cx.parse_program('[?for [user] [yield 1]]') or { panic(err.msg()) }
	code.planar_rewrite(prog) or {
		assert err.msg().contains('CXER0120'), err.msg()
		return
	}
	assert false, 'non-member must refuse the rewrite entry'
}

fn test_report_renders_as_element() {
	c := rw('[?for [in \$x [\$range 1 6]] [order-by \$x desc] [where [= \$x 4]] [yield \$x]]')
	node := code.planar_rewrite_report_node(c.report)
	assert node is cx.Element
	el := node as cx.Element
	assert el.name == 'rewrites'
	assert el.items.len == c.report.applied.len + c.report.declined.len
}

// hint erasure interplay: hints are crossed silently (not rewrites).
fn test_hints_crossed_silently() {
	src := '[?for [in \$x [\$range 1 6]] [order-by \$x] [par] [where [= \$x 4]] [yield \$x]]'
	c := rw(src)
	assert 'sigma-pushdown-below-tau' in rw_kinds(c.report.applied), c.report.str()
	for e in c.report.applied {
		assert !e.detail.contains('par'), e.detail
	}
	rw_assert_equiv(src, c)
}
